const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var sindh = ee.Geometry.Polygon([
    [[66.5, 23.5], [66.5, 28.5], [71.5, 28.5], [71.5, 23.5]]
  ]);

  var date2019 = '2019-09-21';
  var date2020 = '2020-09-21';

  // 2. Data Acquisition - Try Sentinel-2 first
  var s2_2019 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(sindh)
    .filterDate(date2019, '2019-09-22');

  var s2_2020 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(sindh)
    .filterDate(date2020, '2020-09-22');

  // Check collection sizes
  var size2019 = s2_2019.size().getInfo();
  var size2020 = s2_2020.size().getInfo();

  print(`2019 Images: ${size2019}`);
  print(`2020 Images: ${size2020}`);

  // If no Sentinel-2 data, try Landsat 8
  if (size2019 === 0 || size2020 === 0) {
    var ls8_2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(sindh)
      .filterDate(date2019, '2019-09-22');

    var ls8_2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(sindh)
      .filterDate(date2020, '2020-09-22');

    var ls8_size2019 = ls8_2019.size().getInfo();
    var ls8_size2020 = ls8_2020.size().getInfo();

    print(`Landsat 2019 Images: ${ls8_size2019}`);
    print(`Landsat 2020 Images: ${ls8_size2020}`);

    if (ls8_size2019 === 0 || ls8_size2020 === 0) {
      print("<answer>C1</answer>");
      return;
    }

    // Use Landsat 8
    var img2019 = ls8_2019.first();
    var img2020 = ls8_2020.first();

    // Calculate NDWI for Landsat 8 (Green = B3, NIR = B5)
    var ndwi2019 = img2019.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
    var ndwi2020 = img2020.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');

  } else {
    // Use Sentinel-2
    var img2019 = s2_2019.first();
    var img2020 = s2_2020.first();

    // Calculate NDWI for Sentinel-2 (Green = B3, NIR = B8)
    var ndwi2019 = img2019.normalizedDifference(['B3', 'B8']).rename('NDWI');
    var ndwi2020 = img2020.normalizedDifference(['B3', 'B8']).rename('NDWI');
  }

  // 3. Water Detection - threshold NDWI > 0 for water
  var water2019 = ndwi2019.gt(0);
  var water2020 = ndwi2020.gt(0);

  // 4. Count water pixels
  var waterCount2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sindh,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  var waterCount2020 = water2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sindh,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  // Check for valid pixels
  var totalCount2019 = water2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sindh,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  var totalCount2020 = water2020.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sindh,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  print(`2019 Water Pixels: ${waterCount2019}`);
  print(`2020 Water Pixels: ${waterCount2020}`);
  print(`2019 Total Pixels: ${totalCount2019}`);
  print(`2020 Total Pixels: ${totalCount2020}`);

  // 5. Validation & Final Answer
  if (waterCount2019 === null || waterCount2020 === null || 
      isNaN(waterCount2019) || isNaN(waterCount2020)) {
    print("<answer>C3</answer>");
  } else if (totalCount2019 === 0 || totalCount2020 === 0) {
    print("<answer>C2</answer>");
  } else if (waterCount2020 > waterCount2019) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
